 async function updateRecipe(raw?:string){const run=++epoch;card.dataset.ready='false';status.textContent=skinNotice||'Loading coach…';try{if(!viewer){viewer=new CreatureViewer(stage,base,false);settings();}const recipe=raw?importCreature(raw):previewing?importCreature(previewing):loadRecipe(localStorage),active=window.myr5AuthenticatedAccount,owner=typeof active==='string'?active:active?.user?.id;let choices:Record<string,string>={};try{choices=owner?JSON.parse(localStorage.getItem('myr5-editor-skins-v1/account/'+owner)||'{}'):{};}catch{}for(const region of REGIONS){const choice=recipe.materials?.[region];if(choice?.textureId.startsWith('creature-'))choice.textureId='clay';const id=choices?.[region];if(typeof id==='string'&&id.startsWith('creature-'))recipe.materials={...recipe.materials,[region]:{textureId:id,colorId:choice?.colorId??'#7f7d78',sparkle:choice?.sparkle??0,metallic:choice?.metallic??0}};}const loaded=await viewer.setRecipe(recipe);if(!loaded||run!==epoch||closed)return;if(viewer.motion)viewer.motion.sleeping=sleeping;card.dataset.ready='true';status.textContent=skinNotice||'MYR5';const giant=document.body.dataset.screen==='rest';viewer.setStage(viewer.stage==='overlay'?'overlay':giant?'encounter':'pod');viewer.play(giant?'laugh':'greet');holdUntil=performance.now()+(giant?3700:2800);return true;}catch(error){if(run===epoch&&!closed){status.textContent=skinNotice||(error as Error).message;return false;}}}
 async function refreshInstalledSkins(account=window.myr5AuthenticatedAccount){const run=++skinEpoch,owner=typeof account==='string'?account:typeof account?.user?.id==='string'?account.user.id:null,ownerChanged=owner!==skinOwner;skinOwner=owner;if(ownerChanged){skinNotice=null;skinSource?.dispose();skinSource=null;pendingSkinSource?.dispose();pendingSkinSource=null;viewer?.clearSkinState();viewer?.setSkinResolver(undefined);void updateRecipe();}if(!owner){pendingSkinSource?.dispose();pendingSkinSource=null;return;}pendingSkinSource?.dispose();const source=createInstalledCreatureSkinSource({account});pendingSkinSource=source;let rows;try{rows=await source.list();}catch{const active=window.myr5AuthenticatedAccount,activeOwner=typeof active==='string'?active:active?.user?.id;if(closed||run!==skinEpoch||activeOwner!==owner||skinOwner!==owner){source.dispose();if(pendingSkinSource===source)pendingSkinSource=null;return;}if(pendingSkinSource===source)pendingSkinSource=null;source.dispose();skinSource?.dispose();skinSource=null;viewer?.clearSkinState();viewer?.setSkinResolver(undefined);skinNotice='Could not verify installed skins. Check your extra packs and try again.';void updateRecipe();return;}const active=window.myr5AuthenticatedAccount,activeOwner=typeof active==='string'?active:active?.user?.id;if(closed||run!==skinEpoch||activeOwner!==owner||skinOwner!==owner){source.dispose();if(pendingSkinSource===source)pendingSkinSource=null;return;}if(pendingSkinSource===source)pendingSkinSource=null;if(!rows.length){source.dispose();skinSource?.dispose();skinSource=null;viewer?.clearSkinState();viewer?.setSkinResolver(undefined);skinNotice='No verified installed skins. Check your extra packs and try again.';void updateRecipe();return;}const previous=skinSource;skinSource=source;previous?.dispose();skinNotice=null;viewer?.setSkinResolver(source.resolve);void updateRecipe();}
